// src/redux/actions.js

// Sepete ürün eklemek için bir action
export const addToCart = (product) => ({
    type: 'ADD_TO_CART',
    payload: product
  });
  
  // Sepetten ürün silmek için bir action
  export const removeFromCart = (productId) => ({
    type: 'REMOVE_FROM_CART',
    payload: productId
  });
